    glUniform1i(uniloc, 0);
    uniloc = glGetUniformLocation(OrdinaryOBJSpecialCompositeShader,
                                 "SpecialOBJLayerTex");
    glUniform1i(uniloc, 1);
    uniloc = glGetUniformLocation(OrdinaryOBJSpecialCompositeShader,
                                 "ScaledPresentationTex");
    glUniform1i(uniloc, 2);
    uniloc = glGetUniformLocation(OrdinaryOBJSpecialCompositeShader,
                                 "UpscaledMetaTex");
    glUniform1i(uniloc, 3);
