        glBindFramebuffer(GL_FRAMEBUFFER, CaptureBackedRouteGL[i].Handoff3DFB);
        glFramebufferTexture(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, CaptureBackedRouteGL[i].Handoff3DTex, 0);
